import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import {
	OperationalCostCategory,
	OperationalCostPaymentStatus,
	OperationalCostRecurrency,
	type CurrencyCode,
} from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmount } from '../../shared/objects'
import type { FinanceDomainErrors } from '../errors'
import { countOccurrencesInRange, occurrenceWindow } from './recurrence'

export const StatusOverrideSchema = z.object({
	occurrenceDate: z.date(),
	status: z.enum(OperationalCostPaymentStatus),
})

export const OperationalCostSchema = z.object({
	storeId: z.instance(Id),
	category: z.enum(OperationalCostCategory),
	description: z.string().min(1).max(500),
	amount: z.instance(MonetaryAmount).refine(m => m.amountCents > 0, {
		error: 'INVALID_AMOUNT' as FinanceDomainErrors,
	}),
	recurrency: z.enum(OperationalCostRecurrency),
	startDate: z.date(),
	endDate: z.date().nullable(),
	// Sparse deviations from the default per-occurrence status — NOT the
	// full occurrence set. Occurrences are derived at runtime; this only
	// records the ones the merchant flipped away from DEFAULT_OCCURRENCE_STATUS.
	statusOverrides: z.array(StatusOverrideSchema).default([]),
	deletedAt: z.date().nullable(),
})

export type OperationalCostProps = Z.infer<typeof OperationalCostSchema>

export interface OperationalCostOccurrence {
	occurrenceDate: Date
	status: OperationalCostPaymentStatus
}

/**
 * `OperationalCost` aggregate per spec § BC8 Finance. Recurrent or
 * one-off business expense (rent, employee salary, software, etc).
 *
 * Occurrences are **derived at runtime** from `(recurrency, startDate,
 * endDate)` — never stored. Every derived occurrence carries
 * `DEFAULT_OCCURRENCE_STATUS` (PAID) unless `statusOverrides[]` records a
 * deviation for that date. Resolution is therefore **by exclusion**: the
 * full series minus the overridden dates, rather than summing stamped rows.
 *
 * Soft-deleted by `delete()`: row preserved so historical analytics
 * keep their context.
 */
export class OperationalCost extends AggregateRoot<typeof OperationalCostSchema> {
	static override schema = OperationalCostSchema

	/** Status every derived occurrence carries until a `statusOverride` says otherwise. */
	static readonly DEFAULT_OCCURRENCE_STATUS = OperationalCostPaymentStatus.PAID

	static create(data: {
		storeId: string
		category: OperationalCostCategory
		description: string
		amount: { amountCents: number; currency: CurrencyCode }
		recurrency: OperationalCostRecurrency
		startDate: Date
		endDate?: Date
	}): OperationalCost {
		if (data.endDate !== undefined && data.startDate > data.endDate) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'startDate must be <= endDate')
		}
		return new OperationalCost({
			storeId: data.storeId,
			category: data.category,
			description: data.description,
			amount: data.amount,
			recurrency: data.recurrency,
			startDate: data.startDate,
			endDate: data.endDate ?? null,
			statusOverrides: [],
			deletedAt: null,
		})
	}

	update(patch: {
		category?: OperationalCostCategory
		description?: string
		amount?: { amountCents: number; currency: CurrencyCode }
		recurrency?: OperationalCostRecurrency
		startDate?: Date
		endDate?: Date | null
	}): void {
		if (this.deletedAt !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'cannot update a deleted OperationalCost')
		}
		const effectiveStart = patch.startDate ?? this.startDate
		const effectiveEnd = patch.endDate !== undefined ? patch.endDate : this.endDate
		if (effectiveEnd !== null && effectiveStart > effectiveEnd) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'startDate must be <= endDate')
		}
		if (patch.category !== undefined) {
			this.category = patch.category
		}
		if (patch.description !== undefined) {
			this.description = patch.description
		}
		if (patch.amount !== undefined) {
			this.amount = new MonetaryAmount(patch.amount)
		}
		if (patch.recurrency !== undefined) {
			this.recurrency = patch.recurrency
		}
		if (patch.startDate !== undefined) {
			this.startDate = patch.startDate
		}
		if (patch.endDate !== undefined) {
			this.endDate = patch.endDate
		}
		this.validate()
	}

	/**
	 * Records (or clears) a per-occurrence status deviation. Setting an
	 * occurrence back to `DEFAULT_OCCURRENCE_STATUS` *drops* its override so
	 * the overrides array stays minimal — the exclusion set never holds rows
	 * that match the default.
	 */
	setStatusOverride(occurrenceDate: Date, status: OperationalCostPaymentStatus): void {
		if (this.deletedAt !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'cannot override status on a deleted OperationalCost')
		}
		const i = this.statusOverrides.findIndex(o => o.occurrenceDate.getTime() === occurrenceDate.getTime())
		if (status === OperationalCost.DEFAULT_OCCURRENCE_STATUS) {
			if (i >= 0) this.statusOverrides.splice(i, 1)
		} else if (i >= 0) {
			this.statusOverrides[i] = { occurrenceDate, status }
		} else {
			this.statusOverrides.push({ occurrenceDate, status })
		}
		this.validate()
	}

	/** End of the occurrence series: explicit `endDate`, or `now` for an open-ended cost. */
	private effectiveEnd(now: Date): Date {
		return this.endDate ?? now
	}

	/** Status for a derived occurrence — the override if one exists, else the default. */
	resolveStatus(occurrenceDate: Date): OperationalCostPaymentStatus {
		return this.statusOverrides.find(o => o.occurrenceDate.getTime() === occurrenceDate.getTime())?.status ?? OperationalCost.DEFAULT_OCCURRENCE_STATUS
	}

	/**
	 * Strategy 1 — **windowed expansion**. Derives occurrences in `[from, to)`
	 * (bounded by the series) and returns the total count plus only the
	 * requested `page`/`limit` slice, each resolved to its status. At most
	 * `limit` occurrences are materialized regardless of series length.
	 */
	expandOccurrences(input: { from: Date; to: Date; page: number; limit: number; now?: Date }): {
		total: number
		occurrences: OperationalCostOccurrence[]
	} {
		const { total, dates } = occurrenceWindow(
			this.startDate,
			this.effectiveEnd(input.now ?? new Date()),
			this.recurrency,
			input.from,
			input.to,
			input.page,
			input.limit,
		)
		return { total, occurrences: dates.map(occurrenceDate => ({ occurrenceDate, status: this.resolveStatus(occurrenceDate) })) }
	}

	/**
	 * Strategy 2 — **multiplication**. The cost incurred in `[from, to)` is
	 * `(occurrences − cancelled) × amount`: the full derived count, minus the
	 * occurrences excluded by a CANCELLED override. No occurrences are
	 * materialized — counting is O(1) arithmetic. (PAID/UNPAID/OVERDUE are
	 * payment-tracking states; the expense is still incurred, so only
	 * CANCELLED removes it from the total.)
	 */
	incurredCentsBetween(from: Date, to: Date, now?: Date): number {
		const end = this.effectiveEnd(now ?? new Date())
		const count = countOccurrencesInRange(this.startDate, end, this.recurrency, from, to)
		const cancelled = this.statusOverrides.filter(
			o =>
				o.status === OperationalCostPaymentStatus.CANCELLED &&
				o.occurrenceDate.getTime() >= Math.max(from.getTime(), this.startDate.getTime()) &&
				o.occurrenceDate.getTime() < to.getTime() &&
				o.occurrenceDate.getTime() <= end.getTime(),
		).length
		return Math.max(0, count - cancelled) * this.amount.amountCents
	}

	delete(): void {
		if (this.deletedAt !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'OperationalCost already deleted')
		}
		this.deletedAt = new Date()
		this.validate()
	}

	get isDeleted(): boolean {
		return this.deletedAt !== null
	}
}

export interface OperationalCost extends OperationalCostProps {}

