			this.statusOverrides[i] = { occurrenceDate, status }
		} else {
			this.statusOverrides.push({ occurrenceDate, status })
		}
		this.validate()
	}

	/** End of the occurrence series: explicit `endDate`, or `now` for an open-ended cost. */
	private effectiveEnd(now: Date): Date {
		return this.endDate ?? now
	}

	/** Status for a derived occurrence — the override if one exists, else the default. */
	resolveStatus(occurrenceDate: Date): OperationalCostPaymentStatus {
		return this.statusOverrides.find(o => o.occurrenceDate.getTime() === occurrenceDate.getTime())?.status ?? OperationalCost.DEFAULT_OCCURRENCE_STATUS
	}

	/**
	 * Strategy 1 — **windowed expansion**. Derives occurrences in `[from, to)`
	 * (bounded by the series) and returns the total count plus only the
	 * requested `page`/`limit` slice, each resolved to its status. At most
	 * `limit` occurrences are materialized regardless of series length.
	 */
	expandOccurrences(input: { from: Date; to: Date; page: number; limit: number; now?: Date }): {
		total: number
		occurrences: OperationalCostOccurrence[]
	} {
		const { total, dates } = occurrenceWindow(
			this.startDate,
			this.effectiveEnd(input.now ?? new Date()),
			this.recurrency,
			input.from,
			input.to,
			input.page,
			input.limit,
		)
		return { total, occurrences: dates.map(occurrenceDate => ({ occurrenceDate, status: this.resolveStatus(occurrenceDate) })) }
	}

	/**
	 * Strategy 2 — **multiplication**. The cost incurred in `[from, to)` is
	 * `(occurrences − cancelled) × amount`: the full derived count, minus the
	 * occurrences excluded by a CANCELLED override. No occurrences are
	 * materialized — counting is O(1) arithmetic. (PAID/UNPAID/OVERDUE are
	 * payment-tracking states; the expense is still incurred, so only
	 * CANCELLED removes it from the total.)
	 */
	incurredCentsBetween(from: Date, to: Date, now?: Date): number {
		const end = this.effectiveEnd(now ?? new Date())
		const count = countOccurrencesInRange(this.startDate, end, this.recurrency, from, to)
		const cancelled = this.statusOverrides.filter(
			o =>
				o.status === OperationalCostPaymentStatus.CANCELLED &&
				o.occurrenceDate.getTime() >= Math.max(from.getTime(), this.startDate.getTime()) &&
				o.occurrenceDate.getTime() < to.getTime() &&
				o.occurrenceDate.getTime() <= end.getTime(),
		).length
		return Math.max(0, count - cancelled) * this.amount.amountCents
	}

	delete(): void {
		if (this.deletedAt !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'OperationalCost already deleted')
		}
		this.deletedAt = new Date()
		this.validate()
	}

	get isDeleted(): boolean {
		return this.deletedAt !== null
	}
}

export interface OperationalCost extends OperationalCostProps {}

