import { injectable } from 'tsyringe-neo'
import { Handler, z, type Transaction } from '@bk-dash/core-typescript'

import { MonetaryAmountSchema } from '../../shared/objects'
import { OperationalCost } from '../entities/OperationalCost'
import { OperationalCostRepository } from '../repositories/OperationalCostRepository'
import { OperationalCostCreatedEvent } from '../events'
import { OperationalCostCategory, OperationalCostRecurrency } from '@bk-dash/contracts-typescript/wire/enums'

export const CreateOperationalCostInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid(),
	category: z.enum(OperationalCostCategory),
	description: z.string().min(1).max(500),
	amount: MonetaryAmountSchema.refine(m => m.amountCents > 0),
	recurrency: z.enum(OperationalCostRecurrency),
	startDate: z.date(),
	endDate: z.date().optional(),
})

export const CreateOperationalCostOutputSchema = z.object({
	operationalCostId: z.uuid(),
})

/**
 * C41 CreateOperationalCost. Instantiates the aggregate via
 * `OperationalCost.create(...)` (validates the date range), persists,
 * and emits OperationalCostCreatedEvent.
 */
@injectable()
export class CreateOperationalCost extends Handler<typeof CreateOperationalCostInputSchema, typeof CreateOperationalCostOutputSchema> {
	readonly name = 'create_operational_cost' as const
	readonly inputSchema = CreateOperationalCostInputSchema
	readonly outputSchema = CreateOperationalCostOutputSchema

	constructor(private readonly costs: OperationalCostRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const entity = OperationalCost.create({
				storeId: input.storeId,
				category: input.category,
				description: input.description,
				amount: input.amount,
				recurrency: input.recurrency,
				startDate: input.startDate,
				endDate: input.endDate,
			})
			await this.costs.save(entity, tx)

			await this.domainEventRepository.save(
				new OperationalCostCreatedEvent({
					entityId: entity.id.value,
					ownerId: input.storeId,
					payload: { operationalCost: entity.toJSON() },
				}),
				tx,
			)

			return { operationalCostId: entity.id.value }
		})
	}
}

