import { OperationalCostUpdatedEvent } from '../events'
import type { FinanceApplicationErrors } from '../errors'
import { OperationalCostCategory, OperationalCostRecurrency } from '@bk-dash/contracts-typescript/wire/enums'

export const UpdateOperationalCostInputSchema = z.object({
	userId: z.uuid(),
