			const [items, totalRows] = await Promise.all([
				dbc.select().from(operationalCosts).where(where).orderBy(desc(operationalCosts.createdAt)).limit(query.limit).offset(offset),
				dbc
					.select({ value: count() })
					.from(operationalCosts)
					.where(where ?? sql`true`),
			])
			return { items, total: Number(totalRows[0]?.value ?? 0) }
		})
		if (!result.success) throw result.error
		return {
			total: result.data.total,
			items: result.data.items.map(r => this.toDomain(r)),
		}
	}

