		expect(saved?.statusOverrides[0]).toEqual({ occurrenceDate, status: OperationalCostPaymentStatus.UNPAID })

		// Set back to the default (PAID) → override is pruned (exclusion stays minimal).
		await setOverride.execute({ userId: USER, operationalCostId: id, occurrenceDate, status: OperationalCostPaymentStatus.PAID })

		saved = await repo.findById(id)
		expect(saved?.statusOverrides).toHaveLength(0)

		const emitted = await eventRepo().findByType(OperationalCostStatusOverriddenEvent)
		expect(emitted).toHaveLength(2)
	})

	it('Occurrences are derived at runtime, windowed, and resolved by exclusion', async () => {
		// MONTHLY cost starting 2026-06-01, capped by endDate 2026-12-01 → 7 occurrences (Jun..Dec).
		const { operationalCostId: id } = await create.execute({
			userId: USER,
			storeId: STORE,
			category: OperationalCostCategory.RENT,
			description: 'Capped rent',
			amount: { amountCents: 100_000, currency: CurrencyCode.BRL },
			recurrency: OperationalCostRecurrency.MONTHLY,
			startDate: new Date('2026-06-01T00:00:00.000Z'),
			endDate: new Date('2026-12-01T00:00:00.000Z'),
		})

		// Override August to CANCELLED — a deviation from the PAID default.
		await setOverride.execute({
			userId: USER,
			operationalCostId: id,
			occurrenceDate: new Date('2026-08-01T00:00:00.000Z'),
			status: OperationalCostPaymentStatus.CANCELLED,
		})

		const window = { from: new Date('2026-01-01T00:00:00.000Z'), to: new Date('2027-01-01T00:00:00.000Z') }

		const page1 = await occurrences.execute({ operationalCostId: id, ...window, page: 1, limit: 3 })
		expect(page1.total).toBe(7) // total reflects the full series, not the page
		expect(page1.occurrences).toHaveLength(3) // only the requested slice is materialized
		expect(page1.occurrences[0]).toEqual({ occurrenceDate: new Date('2026-06-01T00:00:00.000Z'), status: OperationalCostPaymentStatus.PAID })

		const all = await occurrences.execute({ operationalCostId: id, ...window, page: 1, limit: 50 })
		const august = all.occurrences.find(o => o.occurrenceDate.getTime() === new Date('2026-08-01T00:00:00.000Z').getTime())
		expect(august?.status).toBe(OperationalCostPaymentStatus.CANCELLED) // override wins
		const july = all.occurrences.find(o => o.occurrenceDate.getTime() === new Date('2026-07-01T00:00:00.000Z').getTime())
		expect(july?.status).toBe(OperationalCostPaymentStatus.PAID) // default by exclusion
	})

	it('List returns scoped non-deleted rows', async () => {
		const a = await seed()
		await create.execute({
			userId: USER,
			storeId: STORE,
			category: OperationalCostCategory.APP,
			description: 'SaaS',
			amount: { amountCents: 30_000, currency: CurrencyCode.USD },
			recurrency: OperationalCostRecurrency.MONTHLY,
			startDate: new Date('2026-06-01'),
		})
		// Different store
		await create.execute({
			userId: USER,
			storeId: STORE_OTHER,
			category: OperationalCostCategory.RENT,
			description: 'Other',
			amount: { amountCents: 1000, currency: CurrencyCode.USD },
			recurrency: OperationalCostRecurrency.MONTHLY,
			startDate: new Date('2026-06-01'),
		})

		await del.execute({ userId: USER, operationalCostId: a })

		const r = await list.execute({ storeId: STORE, page: 1, limit: 10 })
		expect(r.total).toBe(1)
		expect(r.items[0]!.description).toBe('SaaS')
	})
})

